enum WaitObservation { case running, interrupted, reaped(Int32), lost(Int32) }
struct ChildOwnership {
    let pid: Int32
    private(set) var isReaped = false
    private(set) var ownershipLost = false
    private(set) var killCommitted = false
    private(set) var rawWaitStatus: Int32?
    init(pid: Int32) throws {
        try require(pid > 0, "positive owned PID")
        self.pid = pid
    }
    mutating func observe(_ observation: WaitObservation) throws {
        try require(!isReaped && !ownershipLost, "terminal ownership")
        switch observation {
        case .running, .interrupted: break
        case .reaped(let status): isReaped = true; rawWaitStatus = status
        case .lost: ownershipLost = true
        }
    }
    mutating func commitKill() throws -> Int32 {
        try require(!isReaped && !ownershipLost && !killCommitted, "KILL ownership/one-shot")
        killCommitted = true
        return pid
    }
}
enum Deadline {
    static func expired(start: UInt64, now: UInt64, numerator: UInt32, denominator: UInt32) throws -> Bool {
        try require(now >= start && numerator > 0 && denominator > 0, "clock/timebase")
        // Exact unsigned 128-bit products as two limbs: Swift.UInt128 itself
        // requires macOS15, while this frozen package retains its macOS14 floor.
        let left = (now - start).multipliedFullWidth(by: UInt64(numerator))
        let right = UInt64(5_000_000_000).multipliedFullWidth(by: UInt64(denominator))
        return left.high > right.high || (left.high == right.high && left.low >= right.low)
    }
}
struct StageSequencer {
    private var index = 0
    private var poisoned = false
    var next: Stage? { poisoned ? nil : Stage(rawValue: index) }
    mutating func finish(_ stage: Stage) throws {
        guard next == stage else { poisoned = true; throw BootstrapFailure.reject("stage order") }
        index += 1
    }
    mutating func reject() { poisoned = true }
}

struct GraphBinding: Equatable, Sendable { let frameHash: String; let merkleRoot: String }
enum ReceiptBinding {
    // Exact closed flat grammars. No general JSON parser, substring scraping,
    // or worker receipt generation; every input byte is consumed once.
    private enum Field { case literal(String), hex }
    private static func parse(_ bytes: [UInt8], _ fields: [(String, Field)]) throws -> [String: String] {
        try require(!bytes.isEmpty && bytes.count <= 262_144, "receipt cap")
        var cursor = 0
        func take(_ literal: String) throws {
            let expected = Array(literal.utf8)
            try require(cursor <= bytes.count && expected.count <= bytes.count - cursor &&
                        bytes[cursor..<(cursor + expected.count)].elementsEqual(expected), "receipt grammar")
            cursor += expected.count
        }
        var hashes: [String: String] = [:]
        try take("{")
        for (index, field) in fields.enumerated() {
            if index > 0 { try take(",") }
            try take("\"\(field.0)\":\"")
            switch field.1 {
            case .literal(let value): try take(value)
            case .hex:
                try require(cursor <= bytes.count && 64 <= bytes.count - cursor, "receipt hash length")
                let value = Array(bytes[cursor..<(cursor + 64)])
                try require(value.allSatisfy { (48...57).contains($0) || (97...102).contains($0) }, "receipt lowerhex")
                hashes[field.0] = String(decoding: value, as: UTF8.self)
                cursor += 64
            }
            try take("\"")
        }
        try take("}")
        try require(cursor == bytes.count, "receipt trailing bytes")
        return hashes
    }
    static func projector(codec: Codec, graph: [UInt8], verifier: [UInt8], roundTrip: [UInt8]) throws -> GraphBinding {
        try require(!graph.isEmpty && graph.count <= 16_777_216, "graph cap")
        let digest = bootstrapSHA256(graph)
        let v = try parse(verifier, [
            ("candidate_sha256", .hex), ("graph_frame_sha256", .hex), ("graph_merkle_root", .hex),
            ("result", .literal("PASS")), ("schema", .literal("ergentics.gate-e.static.verifier-receipt.v1")),
            ("semantic_root", .hex), ("source_authority", .literal(codec.rawValue)),
        ])
        let r = try parse(roundTrip, [
            ("candidate_sha256", .hex), ("graph_frame_sha256", .hex), ("graph_merkle_root", .hex),
            ("original_semantic_root", .hex), ("reconstructed_candidate_sha256", .hex),
            ("reconstructed_graph_frame_sha256", .hex), ("reconstructed_semantic_root", .hex),
            ("result", .literal("PASS")), ("schema", .literal("ergentics.gate-e.static.round-trip-receipt.v1")),
            ("source_authority", .literal(codec.rawValue)),
        ])
        try require(v["candidate_sha256"] == codec.candidateHash &&
                    r["candidate_sha256"] == codec.candidateHash &&
                    r["reconstructed_candidate_sha256"] == codec.candidateHash, "external candidate join")
        try require(v["graph_frame_sha256"] == digest && r["graph_frame_sha256"] == digest &&
                    r["reconstructed_graph_frame_sha256"] == digest, "actual graph join")
        try require(v["semantic_root"] == StaticPins.semanticRoot &&
                    r["original_semantic_root"] == StaticPins.semanticRoot &&
                    r["reconstructed_semantic_root"] == StaticPins.semanticRoot, "external semantic join")
        guard let merkle = v["graph_merkle_root"], r["graph_merkle_root"] == merkle else {
            throw BootstrapFailure.reject("projector Merkle join")
        }
        return GraphBinding(frameHash: digest, merkleRoot: merkle)
    }
    static func join(graph: [UInt8], jsonGraph: [UInt8], cborGraph: [UInt8], receipt: [UInt8],
                     json: GraphBinding, cbor: GraphBinding) throws {
        try require(!graph.isEmpty && graph.count <= 16_777_216 &&
                    graph == jsonGraph && graph == cborGraph && json == cbor, "dual graph bytes")
        let r = try parse(receipt, [
            ("authority_vector", .literal("00000000")), ("cbor_graph_frame_sha256", .hex),
            ("graph_merkle_root", .hex), ("json_graph_frame_sha256", .hex),
            ("projection_write_mask", .literal("00000000")), ("result", .literal("PASS")),
            ("schema", .literal("ergentics.gate-e.static.dual-graph-join-receipt.v1")), ("semantic_root", .hex),
        ])
        let digest = bootstrapSHA256(graph)
        try require(json.frameHash == digest && r["cbor_graph_frame_sha256"] == digest &&
                    r["json_graph_frame_sha256"] == digest && r["graph_merkle_root"] == json.merkleRoot &&
                    r["semantic_root"] == StaticPins.semanticRoot, "independent join receipt")
    }
}

