private func checked(_ call: GEBSCallResult, _ operation: String) throws -> Int64 {
    try require(call.value >= 0 && call.error_number == 0 && call.cleanup_error_number == 0,
                "\(operation):rc=\(call.value):errno=\(call.error_number):cleanup=\(call.cleanup_error_number)")
    return call.value
}
private final class OwnedFD {
