            if parked.value >= 0 && parked.value <= Int64(Int32.max) {
                self.raw = Int32(parked.value)
            }
            _ = try checked(parked, "park")
            _ = try checked(originalClose, "close unparked")
        }
        try require(self.raw >= 32, "FD parking")
    }
