        guard call.value >= 0 && call.value <= Int64(Int32.max) else {
            _ = try checked(call, "open"); throw BootstrapFailure.reject("descriptor range")
        }
        try self.init(adopting: Int32(call.value))
        _ = try checked(call, "open")
    }
    func closeChecked() throws {
        let value = raw
        raw = -1
        if value >= 0 { _ = try checked(gebs_close(value), "close") }
    }
    deinit { if raw >= 0 { _ = gebs_close(raw) } }
}
