    if bytes.isEmpty { return [] }
    try require(bytes.last == 0, "directory listing framing")
    let parts = bytes.dropLast().split(separator: 0, omittingEmptySubsequences: false)
    let resultNames = try parts.map { part -> String in
        try require(!part.isEmpty && !part.contains(47), "directory component")
        guard let value = String(bytes: part, encoding: .utf8) else {
            throw BootstrapFailure.reject("non-UTF8 directory entry")
        }
