private struct Capture: Equatable {
    let metadata: Metadata
    let digest: String
    let bytes: [UInt8]
}
private func readCapture(fd: OwnedFD, parent: OwnedFD, leaf: String, cap: Int,
                         mode: UInt32) throws -> Capture {
    let before = try Metadata.descriptor(fd.raw)
    try before.requireFile(mode: mode, uid: gebs_effective_uid())
    try require(before.size <= Int64(cap), "capture cap")
    var bytes = [UInt8](repeating: 0, count: Int(before.size))
    var offset = 0
    while offset < bytes.count {
        let result = bytes.withUnsafeMutableBytes {
            gebs_pread(fd.raw, $0.baseAddress!.advanced(by: offset), $0.count - offset, Int64(offset))
        }
        if result.value < 0 && result.error_number == 4 { continue }
        let count = try checked(result, "pread")
        try require(count > 0 && count <= Int64(bytes.count - offset), "short pread")
        offset += Int(count)
    }
    var extra: UInt8 = 0
    let eof = gebs_pread(fd.raw, &extra, 1, Int64(bytes.count))
    try require(try checked(eof, "finite EOF") == 0, "file grew")
    let after = try Metadata.descriptor(fd.raw)
    let named = try Metadata.named(parent.raw, leaf)
    try require(before == after && after == named, "file read/name continuity")
    return Capture(metadata: after, digest: bootstrapSHA256(bytes), bytes: bytes)
}
private func writeAll(_ bytes: [UInt8], _ fd: OwnedFD) throws {
    var offset = 0
    while offset < bytes.count {
        let call = bytes.withUnsafeBytes {
            gebs_write(fd.raw, $0.baseAddress!.advanced(by: offset), $0.count - offset)
        }
        if call.value < 0 && call.error_number == 4 { continue }
        let count = try checked(call, "write")
        try require(count > 0 && count <= Int64(bytes.count - offset), "short write")
        offset += Int(count)
    }
}

private enum MachO {
    // Thin arm64, little-endian MH_EXECUTE. All load-command traversal is over
    // held, byte-hashed image bytes. No analyzer subprocesses.
    static func verify(_ bytes: [UInt8], uuid: String) throws {
        func u32(_ offset: Int) throws -> UInt32 {
            try require(offset >= 0 && offset <= bytes.count && 4 <= bytes.count - offset, "Mach-O range")
            return (0..<4).reduce(UInt32(0)) { $0 | (UInt32(bytes[offset + $1]) << (8 * $1)) }
        }
        try require(bytes.count >= 32, "Mach-O header")
        try require(try u32(0) == 0xfeedfacf && u32(4) == 0x0100000c && u32(12) == 2, "Mach-O identity")
        let count = Int(try u32(16)), commandBytes = Int(try u32(20))
        try require(count > 0 && count <= 4096 && commandBytes <= bytes.count - 32, "Mach-O commands")
        let end = 32 + commandBytes
        var offset = 32
        var seenUUID = false, seenVersion = false
        for _ in 0..<count {
            let command = try u32(offset), size = Int(try u32(offset + 4))
            try require(size >= 8 && size % 8 == 0 && offset <= end && size <= end - offset, "Mach-O command size")
            if command == 0x1b {
                try require(!seenUUID && size == 24, "Mach-O UUID count")
                let hex = bytes[(offset + 8)..<(offset + 24)].map { String(format: "%02X", $0) }.joined()
                try require(hex == uuid.replacingOccurrences(of: "-", with: ""), "Mach-O UUID")
                seenUUID = true
            }
            if command == 0x32 {
                try require(!seenVersion && size >= 24, "Mach-O build version count")
                try require(try u32(offset + 8) == 1 && u32(offset + 12) == 0x000e0000 &&
                            u32(offset + 16) == 0x001a0500, "Mach-O platform/minimum/SDK")
                let tools = Int(try u32(offset + 20))
                try require(tools <= 4096 && size == 24 + 8 * tools, "Mach-O tool table")
                seenVersion = true
            }
            offset += size
        }
        try require(offset == end && seenUUID && seenVersion, "Mach-O complete commands")
    }
}
private final class HeldFile {
    let pin: FilePin
    let parents: DirectoryChain
    let leaf: String
    let fd: OwnedFD
    let baseline: Capture
    init(_ pin: FilePin, arena: DirectoryArena) throws {
        guard let slash = pin.path.lastIndex(of: "/") else { throw BootstrapFailure.reject("pin path") }
        let heldLeaf = String(pin.path[pin.path.index(after: slash)...])
        let heldParents = try DirectoryChain(path: String(pin.path[..<slash]), arena: arena)
        let heldFD = try OwnedFD(opened: heldLeaf.withCString { gebs_open_regular_read_at(heldParents.last.raw, $0) })
        let observed = try readCapture(fd: heldFD, parent: heldParents.last, leaf: heldLeaf, cap: pin.size, mode: pin.mode)
        try require(observed.bytes.count == pin.size && observed.digest == pin.digest, "pinned bytes")
        if let device = pin.device, let inode = pin.inode {
            try require(observed.metadata.vnode == Vnode(device: device, inode: inode), "saved vnode")
        }
        if let uuid = pin.image { try MachO.verify(observed.bytes, uuid: uuid) }
        try heldParents.validate()
        self.pin = pin; leaf = heldLeaf; parents = heldParents; fd = heldFD; baseline = observed
    }
    func validate() throws -> Capture {
        try parents.validate()
        let current = try readCapture(fd: fd, parent: parents.last, leaf: leaf, cap: pin.size, mode: pin.mode)
        try require(current == baseline, "immutable admission changed")
        if let uuid = pin.image { try MachO.verify(current.bytes, uuid: uuid) }
        return current
    }
}


private struct InventoryEntry {
    let chain: DirectoryChain
    let children: [String]
