private final class SourceInventory {
    let entries: [InventoryEntry]
    init(arena: DirectoryArena) throws {
        var expected: [String: Set<String>] = [:]
        for pin in StaticPins.sources {
            let prefix = StaticPins.sourceRoot + "/"
            try require(pin.path.hasPrefix(prefix), "source inventory root")
            let parts = pin.path.dropFirst(prefix.count).split(separator: "/").map(String.init)
            var directory = StaticPins.sourceRoot
            for component in parts {
                expected[directory, default: []].insert(component)
                directory += "/" + component
            }
        }
        entries = try expected.keys.sorted().map { path in
            let chain = try DirectoryChain(path: path, arena: arena)
            let before = try Metadata.descriptor(chain.last.raw)
            let children = try names(chain.last.raw)
            try require(children == expected[path]!.sorted(), "exact thirteen-file source topology")
            try require(try Metadata.descriptor(chain.last.raw) == before, "source inventory changed")
            return InventoryEntry(chain: chain, children: children, admitted: before)
        }
    }
    func validate() throws {
        for entry in entries {
            try entry.chain.validate()
            try require(try Metadata.descriptor(entry.chain.last.raw) == entry.admitted &&
                        names(entry.chain.last.raw) == entry.children &&
                        Metadata.descriptor(entry.chain.last.raw) == entry.admitted, "source topology continuity")
        }
    }
}
private final class RunRoot {
    let parent: DirectoryChain
    let fd: OwnedFD
