        let heldFD = try OwnedFD(opened: StaticPins.runLeaf.withCString { gebs_open_directory_at(heldParent.last.raw, $0) })
        let rootMetadata = try Metadata.descriptor(heldFD.raw)
        try require(rootMetadata.type == 0o40000 && rootMetadata.mode == 0o700 &&
                    rootMetadata.uid == gebs_effective_uid(), "run root metadata")
        try require(try Metadata.named(heldParent.last.raw, StaticPins.runLeaf) == rootMetadata && names(heldFD.raw).isEmpty,
                    "new run root join/empty")
        _ = try checked(gebs_sync(heldParent.last.raw), "run root parent sync")
        _ = try checked(gebs_create_workspace(heldFD.raw), "exclusive workspace")
        let heldWorkspace = try OwnedFD(opened: "workspace".withCString { gebs_open_directory_at(heldFD.raw, $0) })
        let workspaceMetadata = try Metadata.descriptor(heldWorkspace.raw)
        try require(workspaceMetadata.type == 0o40000 && workspaceMetadata.mode == 0o700 &&
                    workspaceMetadata.uid == gebs_effective_uid(), "workspace metadata")
        _ = try checked(gebs_sync(heldFD.raw), "workspace parent sync")
        parent = heldParent; fd = heldFD; admitted = rootMetadata
        workspace = heldWorkspace; workspaceAdmitted = workspaceMetadata
        try validate()
    }
