        // Account for the new name immediately if open succeeded, even if later
        // metadata/sync/close fails. Retention never removes a partial leaf.
        if result.value >= 0 { leaves.insert(leaf) }
        let created = try OwnedFD(opened: result)
        let metadata = try Metadata.descriptor(created.raw)
