        try require(observed == expected, "fresh read-only descriptor join")
        try EndpointChecks.input(offset: checked(gebs_cursor(opened.raw), "input cursor"),
                                 readOnly: checked(gebs_access_mode(opened.raw), "input access") == 0,
                                 sourceFD: opened.raw, targetFD: 0)
        return opened
    }
    func validate() throws {
        try parent.validate()
        try require(try Metadata.descriptor(fd.raw).sameDirectoryIdentity(as: admitted) &&
                    Metadata.named(parent.last.raw, StaticPins.runLeaf).sameDirectoryIdentity(as: admitted),
                    "run root rebound")
        try require(try Metadata.descriptor(workspace.raw) == workspaceAdmitted &&
                    Metadata.named(fd.raw, "workspace") == workspaceAdmitted && names(workspace.raw).isEmpty,
                    "workspace changed")
        try require(try Set(names(fd.raw)) == leaves, "unexpected runtime entry")
    }
}
