    private(set) var fd: OwnedFD
    private let created: Metadata
    private(set) var sealed: Capture?
    init(root: RunRoot, name: String, cap: Int) throws {
        self.root = root; self.name = name; self.cap = cap
        fd = try root.create(name)
        created = try Metadata.descriptor(fd.raw)
    }
    func writeInput(_ bytes: [UInt8]) throws {
        try require(sealed == nil && bytes.count <= cap, "input write state")
        try writeAll(bytes, fd)
        let captured = try sealAfterReapOrInputWrite()
        try require(captured.bytes == bytes, "input readback")
    }
    @discardableResult
    func sealAfterReapOrInputWrite() throws -> Capture {
        try require(sealed == nil, "capture already sealed")
        let observed = try readCapture(fd: fd, parent: root.fd, leaf: name, cap: cap, mode: 0o600)
        try require(observed.metadata.sameLeafIdentity(as: created), "output replacement")
        _ = try checked(gebs_sync(fd.raw), "capture sync")
        _ = try checked(gebs_sync(root.fd.raw), "capture name sync")
        try require(try readCapture(fd: fd, parent: root.fd, leaf: name, cap: cap, mode: 0o600) == observed,
                    "capture changed around sync")
        try fd.closeChecked()
        // Writer descriptions are gone before any later role receives a fresh
        // read-only description. The retained reader itself is never rewound.
        fd = try root.freshRead(name, expected: observed)
        sealed = observed
        return observed
    }
    func validate() throws -> Capture {
        let current = try readCapture(fd: fd, parent: root.fd, leaf: name, cap: cap, mode: 0o600)
        if let sealed { try require(current == sealed, "sealed capture changed") }
        else { try require(current.metadata == created && current.bytes.isEmpty, "unentered output changed") }
        return current
    }
}
// This encoder writes only control observations, never worker/graph receipts.
private indirect enum Observation {
    case text(String), signed(Int64), unsigned(UInt64), flag(Bool), null
    case array([Observation]), object([String: Observation])
    var encoded: String {
        switch self {
        case .text(let string):
            let escaped = string.unicodeScalars.map { scalar -> String in
                switch scalar.value {
                case 34: return "\\\""
                case 92: return "\\\\"
                case 0...31: return String(format: "\\u%04x", scalar.value)
                default: return String(scalar)
                }
            }.joined()
            return "\"" + escaped + "\""
        case .signed(let number): return String(number)
        case .unsigned(let number): return String(number)
        case .flag(let bool): return bool ? "true" : "false"
        case .null: return "null"
        case .array(let entries): return "[" + entries.map(\.encoded).joined(separator: ",") + "]"
        case .object(let fields):
            return "{" + fields.keys.sorted().map { Observation.text($0).encoded + ":" + fields[$0]!.encoded }.joined(separator: ",") + "}"
        }
    }
}
private extension Metadata {
    var observation: Observation {
        .object([
            "ctime_nanoseconds": .signed(ctimeNanoseconds), "ctime_seconds": .signed(ctimeSeconds),
            "device": .unsigned(vnode.device), "file_type": .unsigned(UInt64(type)),
            "gid": .unsigned(UInt64(gid)), "inode": .unsigned(vnode.inode), "mode": .unsigned(UInt64(mode)),
            "mtime_nanoseconds": .signed(mtimeNanoseconds), "mtime_seconds": .signed(mtimeSeconds),
            "nlink": .unsigned(nlink), "size": .signed(size), "uid": .unsigned(UInt64(uid)),
        ])
    }
}
private extension Capture {
    func rawObservation(name: String) -> Observation {
        .object(["metadata": metadata.observation, "name": .text(name), "sha256": .text(digest)])
    }
}
private func rawObservation(_ call: GEBSCallResult) -> Observation {
    .object(["cleanup_errno": .signed(Int64(call.cleanup_error_number)), "entered": .signed(Int64(call.entered)),
             "errno": .signed(Int64(call.error_number)), "return": .signed(call.value)])
}
private func rawObservation(_ clock: GEBSClockSample) -> Observation {
    .object(["denominator": .unsigned(UInt64(clock.denominator)), "kernel_result": .signed(Int64(clock.kernel_result)),
             "numerator": .unsigned(UInt64(clock.numerator)), "ticks": .unsigned(clock.ticks)])
}
private func rawObservation(_ spawn: GEBSSpawnResult) -> Observation {
    .object([
        "actions_destroy_entered": .signed(Int64(spawn.actions_destroy_entered)),
        "actions_destroy_result": .signed(Int64(spawn.actions_destroy_result)),
        "attributes_destroy_entered": .signed(Int64(spawn.attributes_destroy_entered)),
        "attributes_destroy_result": .signed(Int64(spawn.attributes_destroy_result)),
        "pid": .signed(Int64(spawn.pid)), "setup_error": .signed(Int64(spawn.setup_error)),
        "setup_step": .signed(Int64(spawn.setup_step)), "spawn_entered": .signed(Int64(spawn.spawn_entered)),
        "spawn_result": .signed(Int64(spawn.spawn_result)),
    ])
}
private final class Journal {
    let root: RunRoot
    private var head: (name: String, capture: Capture)?
    private var records: [(name: String, capture: Capture, fd: OwnedFD)] = []
    private(set) var terminalAttempted = false
    init(root: RunRoot) { self.root = root }
    func publish(_ leaf: String, fields: [String: Observation]) throws {
        if leaf == "90-terminal.json" {
            try require(!terminalAttempted, "terminal attempt consumed")
            terminalAttempted = true
        }
        try validate()
        var record = fields
        record["schema"] = .text("ergentics.gate-e.static.bootstrap-observation.v1")
        record["authority_vector"] = .text("00000000")
        record["projection_write_mask"] = .text("00000000")
        record["gate_e"] = .text("ABSTAIN")
        record["control_commit"] = .text(StaticPins.controlCommit)
        record["control_sha256"] = .text(StaticPins.controlDigest)
        record["historical_pre_B_metadata"] = .text("UNOBSERVED")
        record["historical_build_sequence"] = .text("FAIL_PRE_B_METADATA_CHECK_OMITTED")
        record["previous_leaf"] = head.map { .text($0.name) } ?? .null
        record["previous_sha256"] = head.map { .text($0.capture.digest) } ?? .null
        let bytes = Array(Observation.object(record).encoded.utf8)
        try require(bytes.count <= 262_144, "observation cap")
        let fd = try root.create(leaf)
        try writeAll(bytes, fd)
        let captured = try readCapture(fd: fd, parent: root.fd, leaf: leaf, cap: 262_144, mode: 0o600)
        try require(captured.bytes == bytes, "observation readback")
        _ = try checked(gebs_sync(fd.raw), "observation sync")
        _ = try checked(gebs_sync(root.fd.raw), "observation name sync")
        try require(try readCapture(fd: fd, parent: root.fd, leaf: leaf, cap: 262_144, mode: 0o600) == captured,
                    "observation changed at sync")
        try fd.closeChecked()
        let reader = try root.freshRead(leaf, expected: captured)
        // Advance ancestry only after complete publication/readback/sync/close.
        records.append((leaf, captured, reader))
        head = (leaf, captured)
    }
    func validate() throws {
        try root.validate()
        for record in records {
            try require(try readCapture(fd: record.fd, parent: root.fd, leaf: record.name,
                                        cap: 262_144, mode: 0o600) == record.capture, "retained journal changed")
        }
    }
}
private struct BoundaryCut: Equatable {
    let source: [Capture]
    let images: [Capture]
    let control: Capture
    let endpoints: [String: Capture]
    var observation: Observation {
        .object([
            "source": .array(zip(StaticPins.sources, source).map { $1.rawObservation(name: $0.path) }),
            "images": .array(zip(StaticPins.images, images).map { $1.rawObservation(name: $0.path) }),
            "control": control.rawObservation(name: StaticPins.controlPath),
            "endpoints": .array(endpoints.keys.sorted().map { endpoints[$0]!.rawObservation(name: $0) }),
        ])
    }
}
private final class StageEndpoints {
    let stage: Stage
    let inputs: [Int32: OwnedFD]
    let outputs: [Int32: RuntimeLeaf]
    let workspace: OwnedFD
    private let root: RunRoot
    private let inputBaselines: [Int32: Capture]
    init(stage: Stage, root: RunRoot, retained: inout [String: RuntimeLeaf]) throws {
        self.stage = stage; workspace = root.workspace; self.root = root
        var readers: [Int32: OwnedFD] = [:]
        var writers: [Int32: RuntimeLeaf] = [:]
        var baselines: [Int32: Capture] = [:]
        for (target, name) in stage.inputs.sorted(by: { $0.key < $1.key }) {
            guard let capture = retained[name]?.sealed else { throw BootstrapFailure.reject("missing sealed input") }
            readers[target] = try root.freshRead(name, expected: capture)
            baselines[target] = capture
        }
        for (target, name) in stage.outputs.sorted(by: { $0.key < $1.key }) {
            let cap = target == 2 ? 65_536 : ((target == 3 && stage != .join) || target == 8 ? 16_777_216 : 262_144)
            let leaf = try RuntimeLeaf(root: root, name: name, cap: cap)
            retained[name] = leaf
            writers[target] = leaf
        }
        inputs = readers; outputs = writers; inputBaselines = baselines
        try validate()
    }
    func validate() throws {
        try EndpointChecks.plan(stage: stage, inputs: inputs.mapValues(\.raw), outputs: outputs.mapValues { $0.fd.raw })
        var inputNodes: [Vnode] = []
        for (target, fd) in inputs {
            try EndpointChecks.input(offset: checked(gebs_cursor(fd.raw), "role input offset"),
                                     readOnly: checked(gebs_access_mode(fd.raw), "role input mode") == 0,
                                     sourceFD: fd.raw, targetFD: target)
            let expected = inputBaselines[target]!
            let captured = try readCapture(fd: fd, parent: root.fd, leaf: stage.inputs[target]!,
                                           cap: expected.bytes.count, mode: 0o600)
            try require(captured == expected, "role input complete snapshot join")
            inputNodes.append(captured.metadata.vnode)
        }
        let outputNodes = try outputs.values.map { leaf -> Vnode in
            try require(leaf.sealed == nil, "role output already consumed")
            return try leaf.validate().metadata.vnode
        }
        try EndpointChecks.disjoint(inputs: inputNodes, outputs: outputNodes)
    }
    func closeInputs() throws { for key in inputs.keys.sorted() { try inputs[key]!.closeChecked() } }
    func projectorFDs() -> GEBSProjectorFDs {
        GEBSProjectorFDs(cwd: workspace.raw, input: inputs[0]!.raw,
                        verifier: outputs[1]!.fd.raw, stderr_file: outputs[2]!.fd.raw,
                        graph: outputs[3]!.fd.raw, roundtrip: outputs[4]!.fd.raw)
    }
    func joinFDs() -> GEBSJoinFDs {
        GEBSJoinFDs(cwd: workspace.raw, json_graph: inputs[0]!.raw,
                   json_verifier: inputs[3]!.raw, json_roundtrip: inputs[4]!.raw,
                   cbor_graph: inputs[5]!.raw, cbor_verifier: inputs[6]!.raw, cbor_roundtrip: inputs[7]!.raw,
                   receipt: outputs[1]!.fd.raw, stderr_file: outputs[2]!.fd.raw, graph: outputs[8]!.fd.raw)
    }
}


private final class FullBoundaryAdmission {
    let stage: Stage
    let cut: BoundaryCut
    private let owner: Run
    private let endpoints: StageEndpoints
    private let start: GEBSClockSample
    private let once = OneShotLatch()
    private init(owner: Run, endpoints: StageEndpoints, cut: BoundaryCut, start: GEBSClockSample) {
        self.owner = owner; self.endpoints = endpoints; self.cut = cut; stage = endpoints.stage
        self.start = start
    }
    static func prepare(owner: Run, endpoints: StageEndpoints, expected: BoundaryCut, start: GEBSClockSample) throws -> FullBoundaryAdmission {
        try endpoints.validate()
        let current = try owner.captureBoundary()
        try require(current == expected, "admission changed after durable entry record")
        return FullBoundaryAdmission(owner: owner, endpoints: endpoints, cut: current, start: start)
    }
    private func checkDeadline() throws {
        let current = gebs_clock_sample()
        try require(current.kernel_result == 0 && current.numerator == start.numerator &&
                    current.denominator == start.denominator, "pre-entry clock continuity")
        try require(try !Deadline.expired(start: start.ticks, now: current.ticks,
                                         numerator: start.numerator, denominator: start.denominator), "expired before spawn")
    }
    // Three distinct consumers, no caller argv/env/cwd/role/timeout parameters.
    func consumeJSON() throws -> GEBSSpawnResult {
        try once.consume(); try require(stage == .json, "JSON token stage")
        var descriptors = endpoints.projectorFDs(), result = GEBSSpawnResult()
        try checkDeadline()
        gebs_spawn_json(&descriptors, &result)
        return result
    }
    func consumeCBOR() throws -> GEBSSpawnResult {
        try once.consume(); try require(stage == .cbor, "CBOR token stage")
        var descriptors = endpoints.projectorFDs(), result = GEBSSpawnResult()
        try checkDeadline()
        gebs_spawn_cbor(&descriptors, &result)
        return result
    }
    func consumeJOIN() throws -> GEBSSpawnResult {
        try once.consume(); try require(stage == .join, "JOIN token stage")
        var descriptors = endpoints.joinFDs(), result = GEBSSpawnResult()
        try checkDeadline()
        gebs_spawn_join(&descriptors, &result)
        return result
    }
}
private final class OwnedChild {
    private(set) var state: ChildOwnership
    let start: GEBSClockSample
    private(set) var end: GEBSClockSample?
    private(set) var finalWait: GEBSWaitResult?
    private(set) var kill: GEBSCallResult?
    private(set) var lastPause: GEBSCallResult?
    private(set) var rejected = false
    private var runningReturns: UInt64 = 0
    private var interruptedReturns: UInt64 = 0
    private var pauseEntries: UInt64 = 0
    private var pauseInterruptions: UInt64 = 0
    private var countOverflow = false
    init(pid: Int32, start: GEBSClockSample) throws {
        state = try ChildOwnership(pid: pid)
        self.start = start
    }
    private func increment(_ value: inout UInt64) {
        let (next, overflow) = value.addingReportingOverflow(1)
        if overflow { countOverflow = true; rejected = true } else { value = next }
    }
    // Nothing in this loop throws past an owned unreaped PID. After KILL entry,
    // blocking exact reap is deliberately allowed to remain nonterminal.
    func finish(forceDisposal: Bool) {
        if state.isReaped || state.ownershipLost { return }
        var disposal = forceDisposal
        if forceDisposal { rejected = true }
        while !state.isReaped && !state.ownershipLost {
            let wait = state.killCommitted ? gebs_reap_exact(state.pid) : gebs_wait_exact_nonblocking(state.pid)
            finalWait = wait
            do {
                if wait.call.value == Int64(state.pid) && wait.call.error_number == 0 {
                    // An exact-PID traced stop is not a reap. Do not grant
                    // conservation or signal authority from a nonterminal
                    // status merely because waitpid returned the target PID.
                    guard (wait.exited == 1) != (wait.signaled == 1) else {
                        try state.observe(.lost(-2))
                        rejected = true
                        end = gebs_clock_sample()
                        break
                    }
                    try state.observe(.reaped(wait.status))
                    end = gebs_clock_sample()
                    if let end {
                        if end.kernel_result != 0 || end.numerator != start.numerator || end.denominator != start.denominator {
                            rejected = true
                        } else {
                            do {
                                if try Deadline.expired(start: start.ticks, now: end.ticks,
                                                        numerator: start.numerator, denominator: start.denominator) {
                                    rejected = true
                                }
                            } catch { rejected = true }
                        }
                    }
                    break
                } else if wait.call.value == 0 && wait.call.error_number == 0 {
                    increment(&runningReturns)
                    try state.observe(.running)
                } else if wait.call.value == -1 && wait.call.error_number == 4 {
                    increment(&interruptedReturns)
                    try state.observe(.interrupted)
                } else {
                    try state.observe(.lost(wait.call.error_number))
                    rejected = true
                    end = gebs_clock_sample()
                    break
                }
            } catch {
                // Only a pure state inconsistency can reach this branch. Never
                // signal a slot whose exclusive ownership is no longer proved.
                rejected = true
                return
            }
            if state.killCommitted { continue } // EINTR after blocking reap.
            let clock = gebs_clock_sample()
            do {
                try require(clock.kernel_result == 0 && clock.numerator == start.numerator &&
                            clock.denominator == start.denominator, "clock continuity")
                if try Deadline.expired(start: start.ticks, now: clock.ticks,
                                        numerator: start.numerator, denominator: start.denominator) {
                    disposal = true; rejected = true
                }
            } catch { disposal = true; rejected = true }
            if disposal {
                do {
                    // Commit in memory BEFORE native entry; never repeat on any
                    // returned errno, including EINTR or ESRCH.
                    let exactPID = try state.commitKill()
                    kill = gebs_kill_exact(exactPID)
                } catch { rejected = true; return }
                continue
            }
            let pause = gebs_poll_pause()
            lastPause = pause
            increment(&pauseEntries)
            if pause.value < 0 && pause.error_number == 4 { increment(&pauseInterruptions) }
            else if pause.value != 0 || pause.error_number != 0 { disposal = true; rejected = true }
        }
    }
    var normalSuccess: Bool {
        guard state.isReaped, !state.ownershipLost, !state.killCommitted, !rejected,
              let finalWait, let end else { return false }
        return finalWait.exited == 1 && finalWait.exit_code == 0 && finalWait.signaled == 0 &&
               end.kernel_result == 0 && end.numerator == start.numerator && end.denominator == start.denominator &&
               end.ticks >= start.ticks
    }
    var observation: Observation {
        var fields: [String: Observation] = [
            "count_overflow": .flag(countOverflow), "end": end.map { rawObservation($0) } ?? .null,
            "exact_reaped": .flag(state.isReaped), "kill": kill.map { rawObservation($0) } ?? .null,
            "kill_committed": .flag(state.killCommitted), "last_pause": lastPause.map { rawObservation($0) } ?? .null,
            "normal_exit_zero": .flag(normalSuccess), "ownership_lost": .flag(state.ownershipLost),
            "pause_entries": .unsigned(pauseEntries), "pause_EINTR_returns": .unsigned(pauseInterruptions),
            "pid": .signed(Int64(state.pid)), "rejected": .flag(rejected), "start": rawObservation(start),
            "wait_EINTR_returns": .unsigned(interruptedReturns), "wait_zero_returns": .unsigned(runningReturns),
            "wait_poll_trace_scope": .text("Exact result-class counts; individual polling timestamps/order not retained"),
            "descendant_or_group_conservation": .text("NOT_CLAIMED"),
        ]
        if let wait = finalWait {
            fields["last_wait"] = .object([
                "call": rawObservation(wait.call), "exit_code": .signed(Int64(wait.exit_code)),
                "exited": .signed(Int64(wait.exited)), "signaled": .signed(Int64(wait.signaled)),
                "status": .signed(Int64(wait.status)), "term_signal": .signed(Int64(wait.term_signal)),
            ])
        } else { fields["last_wait"] = .null }
        return .object(fields)
    }
}
private final class Run {
    private var directoryArena: DirectoryArena?
    private var sources: [HeldFile] = []
    private var images: [HeldFile] = []
    private var control: HeldFile?
    private var inventory: SourceInventory?
    private var root: RunRoot?
    private var journal: Journal?
    private var retained: [String: RuntimeLeaf] = [:]
    private var sequencer = StageSequencer()
    private var active: OwnedChild?
    private var lastSpawn: GEBSSpawnResult?
    private var enteredStage: Stage?
    private var audits: [Observation] = []
    private var jsonBinding: GraphBinding?
    private var cborBinding: GraphBinding?

    func execute() throws {
        // Byte-identical build candidates are freshly admitted, not promoted
        // from the historical build's missing pre-B metadata observation.
        try require(bootstrapSHA256(StaticPins.jsonBytes) == Codec.json.candidateHash &&
                    bootstrapSHA256(StaticPins.cborBytes) == Codec.cbor.candidateHash, "embedded input identities")
        var semanticPreimage = Array("ERGENTICS-GATE-E-STATIC-SEMANTIC-V1".utf8) + [0]
        semanticPreimage += (0..<8).reversed().map { UInt8(truncatingIfNeeded: UInt64(StaticPins.jsonBytes.count) >> (8 * $0)) }
        semanticPreimage += StaticPins.jsonBytes
        try require(bootstrapSHA256(semanticPreimage) == StaticPins.semanticRoot, "embedded semantic commitment")
        let arena = try DirectoryArena()
        directoryArena = arena
        sources = try StaticPins.sources.map { try HeldFile($0, arena: arena) }
        images = try StaticPins.images.map { try HeldFile($0, arena: arena) }
        control = try HeldFile(FilePin(path: StaticPins.controlPath, size: 28_799, digest: StaticPins.controlDigest,
                                      mode: 0o644, device: nil, inode: nil, image: nil), arena: arena)
        inventory = try SourceInventory(arena: arena)
        // This one serial owner configures SIGCHLD before any fixed child.
        let sigchld = gebs_configure_sigchld()
        _ = try checked(sigchld, "SIGCHLD default/no-auto-reap")
        let createdRoot = try RunRoot(arena: arena)
        root = createdRoot
        let log = Journal(root: createdRoot)
        journal = log
        let json = try RuntimeLeaf(root: createdRoot, name: "candidate-json.bin", cap: 4_194_304)
        retained[json.name] = json
        try json.writeInput(StaticPins.jsonBytes)
        let cbor = try RuntimeLeaf(root: createdRoot, name: "candidate-cbor.bin", cap: 4_194_304)
        retained[cbor.name] = cbor
        try cbor.writeInput(StaticPins.cborBytes)
        let cut = try captureBoundary()
        try log.publish("00-start.json", fields: [
            "boundary": cut.observation, "event": .text("STATIC_BOOTSTRAP_START"),
            "sigchld_configuration": rawObservation(sigchld),
            "budgets_are_not_call_observations": .flag(true),
            "maximum_fixed_child_entries": .unsigned(3), "maximum_KILL_commitments_per_owned_child": .unsigned(1),
            "source_subject_commit": .text("04c5324ccfc6984ad7c407e93238cc44f9ce22dd"),
            "source_subject_tree": .text("10615a2d66720b70ecafa891ab26e96ac9ee812e"),
            "source_subject_identity": .text("2c25246de1b50148d8193167880828815b17c80e8ee66a09dec45b1430178fc1"),
            "live_source_admission": .flag(false), "mapped_image_join": .flag(false),
            "time": rawObservation(gebs_clock_sample()),
        ])
        try runJSON()
        try runCBOR()
        try runJOIN()
        try require(sequencer.next == nil && audits.count == 3, "all static stages")
        let final = try captureBoundary()
        try log.publish("90-terminal.json", fields: [
            "boundary": final.observation, "event": .text("STATIC_BOOTSTRAP_TERMINAL"),
            "result": .text("STATIC_GRAPH_JOIN_PASS_AT_RECORDED_CUT"),
            "stages": .array(audits), "whole_invocation_also_requires_normal_exit_zero": .flag(true),
            "time": rawObservation(gebs_clock_sample()),
        ])
        try log.validate()
        _ = try captureBoundary()
    }
    func captureBoundary() throws -> BoundaryCut {
        guard let inventory, let control, let root else { throw BootstrapFailure.reject("admission owner absent") }
        try inventory.validate()
        let sourceCut = try sources.map { try $0.validate() }
        let imageCut = try images.map { try $0.validate() }
        let controlCut = try control.validate()
        try root.validate()
        try journal?.validate()
        var endpoints: [String: Capture] = [:]
        for name in retained.keys.sorted() { endpoints[name] = try retained[name]!.validate() }
        // Full metadata equality + whole-file digests actually evaluated above.
        try BoundaryChecks.requireComplete(sourceMetadata: sourceCut.count, sourceDigests: sourceCut.count,
                                           imageMetadata: imageCut.count, imageDigests: imageCut.count, endpoints: true)
        try inventory.validate()
        return BoundaryCut(source: sourceCut, images: imageCut, control: controlCut, endpoints: endpoints)
    }
    private func prepare(_ stage: Stage) throws -> (FullBoundaryAdmission, StageEndpoints, GEBSClockSample) {
        try require(sequencer.next == stage, "fixed next stage")
        guard let root, let journal else { throw BootstrapFailure.reject("runtime owner absent") }
        let endpoints = try StageEndpoints(stage: stage, root: root, retained: &retained)
        let cut = try captureBoundary()
        let clock = gebs_clock_sample()
        try require(clock.kernel_result == 0 && clock.numerator > 0 && clock.denominator > 0, "pre-spawn clock")
        try journal.publish(stage.entryLeaf, fields: [
            "boundary": cut.observation, "event": .text("FIXED_STAGE_ENTRY_INTENT"),
            "stage": .text(stage.label), "start": rawObservation(clock),
            "spawn_entered_observation": .null,
            "deadline_nanoseconds": .unsigned(5_000_000_000),
        ])
        let token = try FullBoundaryAdmission.prepare(owner: self, endpoints: endpoints, expected: cut, start: clock)
        return (token, endpoints, clock)
    }
    private func runJSON() throws {
        let (token, endpoints, start) = try prepare(.json)
        try acceptSpawn(try token.consumeJSON(), endpoints: endpoints, start: start)
    }
    private func runCBOR() throws {
        let (token, endpoints, start) = try prepare(.cbor)
        try acceptSpawn(try token.consumeCBOR(), endpoints: endpoints, start: start)
    }
    private func runJOIN() throws {
        let (token, endpoints, start) = try prepare(.join)
        try acceptSpawn(try token.consumeJOIN(), endpoints: endpoints, start: start)
    }
    private func acceptSpawn(_ spawn: GEBSSpawnResult, endpoints: StageEndpoints, start: GEBSClockSample) throws {
        // First retain the raw result, then the exact PID owner; no journal,
        // close, capture parsing, or teardown-error throw precedes ownership.
        lastSpawn = spawn
        enteredStage = endpoints.stage
        try require(spawn.spawn_entered == 1 && spawn.spawn_result == 0 && spawn.pid > 1, "fixed spawn failed")
        let child = try OwnedChild(pid: spawn.pid, start: start) // positive PID check already satisfied.
        active = child
        let teardownFailed = spawn.actions_destroy_result != 0 || spawn.attributes_destroy_result != 0
        child.finish(forceDisposal: teardownFailed)
        try require(child.state.isReaped && !child.state.ownershipLost, "exact reap/conservation missing")
        try endpoints.closeInputs()
        for target in endpoints.outputs.keys.sorted() { try endpoints.outputs[target]!.sealAfterReapOrInputWrite() }
        let cut = try captureBoundary()
        try require(child.normalSuccess && !teardownFailed, "child exit/deadline/teardown failure")
        let stage = endpoints.stage
        func bytes(_ name: String) throws -> [UInt8] {
            guard let result = retained[name]?.sealed?.bytes else { throw BootstrapFailure.reject("missing capture") }
            return result
        }
        try require(try bytes(stage.outputs[2]!).isEmpty, "nonempty stderr")
        switch stage {
        case .json:
            jsonBinding = try ReceiptBinding.projector(codec: .json, graph: bytes("12-json-graph.json"),
                verifier: bytes("11-json-verifier.json"), roundTrip: bytes("13-json-roundtrip.json"))
        case .cbor:
            cborBinding = try ReceiptBinding.projector(codec: .cbor, graph: bytes("22-cbor-graph.json"),
                verifier: bytes("21-cbor-verifier.json"), roundTrip: bytes("23-cbor-roundtrip.json"))
            try require(jsonBinding == cborBinding && bytes("12-json-graph.json") == bytes("22-cbor-graph.json"),
                        "cross-codec external graph join")
        case .join:
            guard let jsonBinding, let cborBinding else { throw BootstrapFailure.reject("missing projector joins") }
            try ReceiptBinding.join(graph: bytes("32-authoritative-static-graph.json"), jsonGraph: bytes("12-json-graph.json"),
                cborGraph: bytes("22-cbor-graph.json"), receipt: bytes("31-join-receipt.json"), json: jsonBinding, cbor: cborBinding)
        }
        guard let journal else { throw BootstrapFailure.reject("journal missing") }
        let audit: Observation = .object(["stage": .text(stage.label), "spawn": rawObservation(spawn), "child": child.observation])
        try journal.publish(stage.exitLeaf, fields: [
            "boundary": cut.observation, "event": .text("FIXED_STAGE_COMPLETE"),
            "result": .text("PASS_STATIC_STAGE"), "stage": .text(stage.label),
            "spawn": rawObservation(spawn), "child": child.observation,
        ])
        audits.append(audit)
        try sequencer.finish(stage)
    }
    func fail(_ error: Error) {
        sequencer.reject()
        // Exact ownership survives every post-spawn throw. This does not adopt
        // old processes or infer signal authority from a journal PASS.
        active?.finish(forceDisposal: true)
        guard let journal, !journal.terminalAttempted else { return }
        var fields: [String: Observation] = [
            "event": .text("STATIC_BOOTSTRAP_TERMINAL"), "result": .text("FAIL_NO_RETRY"),
            "error": .text(String(describing: error)), "completed_stages": .array(audits),
            "entered_stage": enteredStage.map { .text($0.label) } ?? .null,
            "last_spawn": lastSpawn.map { rawObservation($0) } ?? .null,
            "last_child": active.map(\.observation) ?? .null,
            "time": rawObservation(gebs_clock_sample()),
        ]
        fields["conservation"] = .text(active == nil ? "NO_SUCCESSFUL_CHILD_CAPTURED" :
            (active!.state.isReaped ? "EXACT_CHILD_REAPED_NO_GROUP_CLAIM" : "UNPROVEN"))
        // One terminal attempt. Failure retains the partial leaf/prefix and is
        // not repaired, replaced, retried, or reinterpreted as complete.
        try? journal.publish("90-terminal.json", fields: fields)
    }
}
public enum GateEStaticBootstrap {
    /// Closed coordinator only. No caller-selected inputs or runtime settings.
    /// Future entry requires a separately frozen, explicitly approved launch.
    public static func run() -> Int32 {
        let owner = Run()
        do { try owner.execute(); return 0 }
        catch { owner.fail(error); return 70 }
    }
}
